-- ═══════════════════════════════════════════════════════════════════════════
-- MIGRATION db-games — contenu et règles des mini-jeux en base (octobre 2026)
--
-- Jusqu'ici, le contenu de chaque jeu (déchets, mots, durées) et ses règles
-- (nombre de manches, points, vies, chrono) étaient écrits dans les pages
-- jeu-*.html, et la liste des jeux recopiée à cinq endroits. Ils vivent
-- désormais dans db-games et s'éditent depuis /jeux-admin, comme les cours.
--
--   • jeux          : un jeu = ses textes, ses règles, son contenu (JSON
--                     validés par services/games-api/jeux/_jeux.php)
--   • jeux_versions : copie complète d'un jeu écrite AVANT chaque sauvegarde
--   • scores.score_max : score maximum en vigueur au moment de la partie. Si
--                     une règle change le maximum, les anciens scores sont
--                     convertis à la nouvelle échelle à l'affichage
--                     (score × max actuel ÷ max d'époque) : rien n'est réécrit.
--
-- Les 4 jeux sont insérés avec le contenu exact des pages au moment de la
-- migration (INSERT IGNORE : un jeu déjà présent n'est jamais écrasé).
-- Rejouable. Généré à partir des pages, ne pas éditer le bloc INSERT à la main.
-- ═══════════════════════════════════════════════════════════════════════════

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `jeux` (
  `slug`        varchar(40)  NOT NULL,
  `nom`         varchar(80)  NOT NULL,
  `emoji`       varchar(16)  NOT NULL DEFAULT '🎮',
  `description` varchar(300) NOT NULL DEFAULT '',
  `statut`      enum('brouillon','publie') NOT NULL DEFAULT 'publie',
  `ordre`       int          NOT NULL DEFAULT 0,
  `regles`      text         NOT NULL,   -- JSON, forme propre à chaque jeu
  `messages`    text         NOT NULL,   -- JSON [{min, emoji, texte}] (fin de partie)
  `items`       mediumtext   NOT NULL,   -- JSON, éléments tirés au hasard à chaque partie
  `score_max`   int          NOT NULL,   -- calculé depuis les règles, jamais saisi
  `xp_reserve`  int          NOT NULL DEFAULT 50,
  `maj_at`      datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `maj_par`     varchar(100) DEFAULT NULL,
  PRIMARY KEY (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `jeux_versions` (
  `id`         int          NOT NULL AUTO_INCREMENT,
  `slug`       varchar(40)  NOT NULL,
  `contenu`    mediumtext   NOT NULL,   -- JSON : l'état complet du jeu avant la sauvegarde
  `auteur`     varchar(100) DEFAULT NULL,
  `created_at` datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `slug_date` (`slug`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE `scores` ADD COLUMN IF NOT EXISTS `score_max` int DEFAULT NULL AFTER `score`;

-- Scores déjà joués : maximum des règles d'avant la migration.
UPDATE `scores` SET `score_max` = CASE `jeu_id`
    WHEN 'mot-mystere'    THEN 80
    WHEN 'compost-ou-pas' THEN 12
    WHEN 'temps-decompo'  THEN 30
    WHEN 'tri-eclair'     THEN 15
  END
 WHERE `score_max` IS NULL;

INSERT IGNORE INTO `jeux`
  (`slug`, `nom`, `emoji`, `description`, `statut`, `ordre`, `regles`, `messages`, `items`, `score_max`, `xp_reserve`)
VALUES
('mot-mystere', 'Mot mystère', '🔤', 'Reconstitue les mots du compostage à partir de lettres mélangées.', 'publie', 0, '{"nb_mots":8,"points":[10,6,3]}', '[{"min":0.9,"emoji":"🏆","texte":"Incroyable, tu es un maître du compost !"},{"min":0.6,"emoji":"🌟","texte":"Très beau score, le vocabulaire est presque maîtrisé !"},{"min":0.3,"emoji":"🌱","texte":"Pas mal ! Va relire les cours pour progresser."},{"min":0,"emoji":"🪱","texte":"Les vers de compost te conseillent un petit tour par les cours 😉"}]', '[{"mot":"COMPOST","indice":"Le résultat de la décomposition des biodéchets","emoji":"🌱"},{"mot":"LOMBRIC","indice":"Le ver de terre, grand allié du composteur","emoji":"🪱"},{"mot":"EISENIA","indice":"Le nom scientifique du ver de compost","emoji":"🔬"},{"mot":"HUMUS","indice":"Matière sombre et fertile issue de la décomposition","emoji":"🟤"},{"mot":"AZOTE","indice":"Élément apporté par les matières vertes et humides","emoji":"💚"},{"mot":"CARBONE","indice":"Élément apporté par les matières brunes et sèches","emoji":"🍂"},{"mot":"TERREAU","indice":"Support de culture riche, parfait pour les semis","emoji":"🌾"},{"mot":"PAILLAGE","indice":"Couverture protectrice du sol au jardin","emoji":"🍁"},{"mot":"BACTERIE","indice":"Micro-organisme décomposeur invisible à l''œil nu","emoji":"🦠"},{"mot":"CLOPORTE","indice":"Petit crustacé terrestre qui vit dans le compost","emoji":"🐛"},{"mot":"DECHET","indice":"Ce que le compostage transforme en ressource","emoji":"🗑️"},{"mot":"ENGRAIS","indice":"Le compost en est un, 100% naturel et gratuit","emoji":"🌻"}]', 80, 50),
('compost-ou-pas', 'Compost ou pas ?', '♻️', 'Décide si chaque déchet va au compost ou à la poubelle.', 'publie', 1, '{"nb_items":12}', '[{"min":0.9,"emoji":"🏆","texte":"Parfait, ton bac à compost est entre de bonnes mains !"},{"min":0.65,"emoji":"🌟","texte":"Très bien ! Encore quelques pièges à éviter."},{"min":0.4,"emoji":"🌱","texte":"Pas mal, mais le cours sur les bases du compostage t''aiderait !"},{"min":0,"emoji":"🪱","texte":"Ton compost risque l''indigestion 😅 Va voir les cours !"}]', '[{"nom":"Épluchures de légumes","emoji":"🥕","cat":"oui","info":"Parfaites pour le compost, c''est la base !"},{"nom":"Marc de café","emoji":"☕","cat":"oui","info":"Excellent ! Les vers en raffolent, filtre papier compris."},{"nom":"Coquilles d''œuf","emoji":"🥚","cat":"oui","info":"Oui ! Écrasées, elles apportent du calcium."},{"nom":"Tonte de pelouse","emoji":"🌱","cat":"oui","info":"Oui, en couches fines pour éviter que ça fermente."},{"nom":"Feuilles mortes","emoji":"🍂","cat":"oui","info":"Oui ! Une super source de carbone."},{"nom":"Viande","emoji":"🥩","cat":"attention","info":"Possible dans un compost mûr et actif : en petits morceaux, enfouis au centre. Dans un bac jeune ou peu brassé, odeurs et rongeurs garantis."},{"nom":"Poisson","emoji":"🐟","cat":"attention","info":"Même règle que la viande : seulement dans un compost bien établi, enfoui et recouvert. À proscrire sur un balcon."},{"nom":"Pain rassis","emoji":"🍞","cat":"attention","info":"En petits morceaux humidifiés et enfouis. Laissé sec en surface, il moisit et attire les rongeurs."},{"nom":"Cendres de bois","emoji":"🔥","cat":"attention","info":"Une fine poignée de temps en temps, bien répartie : elles apportent du potassium. En quantité, elles rendent le compost trop basique et le bloquent."},{"nom":"Essuie-tout","emoji":"🧻","cat":"attention","info":"Oui s''il n''a servi qu''à essuyer de l''eau ou des aliments. Imbibé de produit ménager, il contamine tout le bac."},{"nom":"Sachets de thé","emoji":"🍵","cat":"attention","info":"Le thé, toujours. Le sachet, seulement s''il est en papier non plastifié, et sans l''agrafe : beaucoup contiennent du polypropylène."},{"nom":"Produits laitiers","emoji":"🧀","cat":"attention","info":"Un reste de fromage ou de yaourt enfoui dans un compost mûr se dégrade sans problème. En quantité, ça rancit, ça sent fort et ça attire les nuisibles."},{"nom":"Os","emoji":"🦴","cat":"non","info":"Beaucoup trop longs à se décomposer."},{"nom":"Huile de friture","emoji":"🛢️","cat":"non","info":"Non : elle étouffe les micro-organismes."},{"nom":"Sac plastique « biodégradable »","emoji":"🛍️","cat":"non","info":"Méfiance : la plupart ne se dégradent pas en compost domestique."},{"nom":"Plantes malades","emoji":"🥀","cat":"non","info":"Non : les maladies peuvent survivre et contaminer le jardin."}]', 12, 50),
('temps-decompo', 'Combien de temps ?', '⏳', 'Devine combien de temps chaque déchet met à se décomposer.', 'publie', 2, '{"nb_courts":6,"nb_longs":4,"seuils":[{"d":0.05,"pts":3},{"d":0.12,"pts":2},{"d":0.2,"pts":1}]}', '[{"min":0.85,"emoji":"🏆","texte":"Impressionnant ! Le temps n''a plus de secret pour toi."},{"min":0.6,"emoji":"🌟","texte":"Très bonne intuition ! Quelques surprises quand même, non ?"},{"min":0.35,"emoji":"🌱","texte":"Pas mal ! La nature est parfois plus lente qu''on ne croit…"},{"min":0,"emoji":"🪱","texte":"Surpris par les réponses ? C''est bien le but du jeu 😄"}]', '[{"nom":"un trognon de pomme","emoji":"🍎","jours":60,"info":"Environ 2 mois. Bien plus long qu''on ne l''imagine — ne le jette pas dans la nature !"},{"nom":"une peau de banane","emoji":"🍌","jours":45,"info":"Environ 6 semaines au compost… et jusqu''à 2 ans en montagne, où il fait froid et sec !"},{"nom":"des épluchures de légumes","emoji":"🥕","jours":30,"info":"Environ 1 mois : les stars du compost, elles nourrissent vite le sol."},{"nom":"du marc de café","emoji":"☕","jours":21,"info":"À peine 3 semaines. Les vers de terre en raffolent !"},{"nom":"du pain","emoji":"🍞","jours":14,"info":"Environ 2 semaines, l''un des plus rapides à se décomposer."},{"nom":"de l''essuie-tout","emoji":"🧻","jours":30,"info":"Environ 1 mois, s''il n''a pas touché de produits chimiques."},{"nom":"des feuilles mortes","emoji":"🍂","jours":180,"info":"De 3 à 6 mois : une super source de carbone pour le compost."},{"nom":"une peau d''orange","emoji":"🍊","jours":180,"info":"Environ 6 mois : la peau des agrumes est épaisse et résistante."},{"nom":"un sachet de thé en papier","emoji":"🍵","jours":90,"info":"Environ 3 mois. Attention aux sachets en nylon, qui ne se décomposent pas !"},{"nom":"un journal","emoji":"📰","jours":90,"info":"Environ 3 mois : le papier se composte très bien en petits morceaux."},{"nom":"du carton","emoji":"📦","jours":150,"info":"Environ 5 mois : déchiré et humide, il se composte très bien."},{"nom":"une coquille d''œuf","emoji":"🥚","jours":365,"info":"Environ 1 an pour une coquille entière — écrase-la pour accélérer et apporter du calcium !"},{"nom":"un t-shirt en coton non traité","emoji":"👕","jours":270,"info":"De 6 mois à 1 an : le coton pur est une fibre naturelle, contrairement au polyester. Teintures, apprêts et mélanges synthétiques rallongent nettement ce délai."},{"nom":"un bouchon de liège","emoji":"🍾","jours":1095,"info":"Environ 3 ans. Naturel, mais très lent — il se recycle mieux qu''il ne se composte."},{"nom":"un chewing-gum","emoji":"🍬","jours":1825,"info":"Environ 5 ans ! Le chewing-gum est fait de gomme… synthétique, un dérivé du plastique."},{"nom":"un mégot de cigarette","emoji":"🚬","jours":3650,"info":"Environ 10 ans, et un seul mégot pollue jusqu''à 500 litres d''eau."},{"nom":"une boîte de conserve","emoji":"🥫","jours":18250,"info":"Environ 50 ans. L''acier rouille lentement… mais se recycle à l''infini !"},{"nom":"une canette en aluminium","emoji":"🥤","jours":73000,"info":"Environ 200 ans dans la nature. Recyclée, elle redevient canette en 60 jours !"},{"nom":"un sac plastique","emoji":"🛍️","jours":146000,"info":"Environ 400 ans. Et il ne disparaît pas : il se fragmente en microplastiques."},{"nom":"une bouteille en plastique","emoji":"🧴","jours":164250,"info":"450 ans ! La bouteille jetée aujourd''hui sera encore là pour tes arrière-arrière-…-petits-enfants."},{"nom":"une couche jetable","emoji":"👶","jours":164250,"info":"Environ 450 ans. Un bébé en utilise près de 4000 avant la propreté…"},{"nom":"une brosse à dents","emoji":"🪥","jours":182500,"info":"Environ 500 ans. Toutes les brosses à dents en plastique jamais fabriquées existent encore."},{"nom":"un fil de pêche","emoji":"🎣","jours":219000,"info":"Environ 600 ans, et un vrai piège mortel pour les animaux marins."},{"nom":"une barquette en polystyrène","emoji":"🥡","jours":365000,"info":"Jusqu''à 1000 ans ! Le polystyrène est quasi indestructible dans la nature."}]', 30, 50),
